/*
 * KIDS_PORTAL_V1 revision 7 — delegated, evidence-based statistical semantics.
 * Revision 6 stays immutable and executable. No observation value is seeded here.
 */
IF OBJECT_ID(N'platform.statistical_unit',N'U') IS NULL CREATE TABLE platform.statistical_unit(
 unit_id BIGINT IDENTITY PRIMARY KEY,unit_code NVARCHAR(120) NOT NULL UNIQUE,quantity_kind VARCHAR(24) NOT NULL,
 scale_factor DECIMAL(28,10) NOT NULL,denominator_text NVARCHAR(500) NULL,title NVARCHAR(255) NOT NULL,status VARCHAR(24) NOT NULL
);
IF OBJECT_ID(N'platform.data_quality_policy',N'U') IS NULL CREATE TABLE platform.data_quality_policy(
 quality_policy_id BIGINT IDENTITY PRIMARY KEY,policy_code NVARCHAR(120) NOT NULL UNIQUE,status VARCHAR(24) NOT NULL,rules_json NVARCHAR(MAX) NOT NULL,
 CONSTRAINT ck_data_quality_policy_json CHECK(ISJSON(rules_json)=1)
);
IF OBJECT_ID(N'platform.confidentiality_policy',N'U') IS NULL CREATE TABLE platform.confidentiality_policy(
 confidentiality_policy_id BIGINT IDENTITY PRIMARY KEY,policy_code NVARCHAR(120) NOT NULL UNIQUE,status VARCHAR(24) NOT NULL,rules_json NVARCHAR(MAX) NOT NULL,
 CONSTRAINT ck_confidentiality_policy_json CHECK(ISJSON(rules_json)=1)
);
IF OBJECT_ID(N'platform.metric_semantic_profile',N'U') IS NULL CREATE TABLE platform.metric_semantic_profile(
 metric_semantic_profile_id BIGINT IDENTITY PRIMARY KEY,metric_id BIGINT NOT NULL UNIQUE,source_resource_external_key NVARCHAR(255) NOT NULL,
 unit_id BIGINT NOT NULL,inference_method VARCHAR(48) NOT NULL,inference_confidence DECIMAL(5,4) NOT NULL,inference_rationale NVARCHAR(1000) NOT NULL,
 approved_basis NVARCHAR(255) NOT NULL,status VARCHAR(24) NOT NULL,
 CONSTRAINT fk_metric_semantic_profile_metric FOREIGN KEY(metric_id) REFERENCES platform.metric(metric_id),
 CONSTRAINT fk_metric_semantic_profile_unit FOREIGN KEY(unit_id) REFERENCES platform.statistical_unit(unit_id),
 CONSTRAINT ck_metric_semantic_confidence CHECK(inference_confidence BETWEEN 0 AND 1)
);
IF OBJECT_ID(N'platform.statistical_semantic_binding',N'U') IS NULL CREATE TABLE platform.statistical_semantic_binding(
 statistical_semantic_binding_id BIGINT IDENTITY PRIMARY KEY,dataflow_id BIGINT NOT NULL,carrier_external_code NVARCHAR(255) NOT NULL,
 metric_id BIGINT NOT NULL,unit_id BIGINT NOT NULL,aggregation VARCHAR(24) NOT NULL,obs_status VARCHAR(8) NOT NULL,conf_status VARCHAR(8) NOT NULL,
 quality_policy_id BIGINT NOT NULL,confidentiality_policy_id BIGINT NOT NULL,status VARCHAR(24) NOT NULL,
 CONSTRAINT uq_statistical_semantic_binding UNIQUE(dataflow_id,carrier_external_code),
 CONSTRAINT fk_stat_semantic_dataflow FOREIGN KEY(dataflow_id) REFERENCES platform.statistical_dataflow(dataflow_id),
 CONSTRAINT fk_stat_semantic_metric FOREIGN KEY(metric_id) REFERENCES platform.metric(metric_id),
 CONSTRAINT fk_stat_semantic_unit FOREIGN KEY(unit_id) REFERENCES platform.statistical_unit(unit_id),
 CONSTRAINT fk_stat_semantic_quality FOREIGN KEY(quality_policy_id) REFERENCES platform.data_quality_policy(quality_policy_id),
 CONSTRAINT fk_stat_semantic_confidentiality FOREIGN KEY(confidentiality_policy_id) REFERENCES platform.confidentiality_policy(confidentiality_policy_id)
);

MERGE platform.statistical_unit t USING(VALUES
(N'COUNT_EVENT','EVENT',1,NULL,N'Count of events'),(N'COUNT_CASE','CASE',1,NULL,N'Count of cases'),(N'PERSON','PERSON',1,NULL,N'Persons'),
(N'THOUSAND_PERSONS','PERSON',1000,NULL,N'Thousand persons'),(N'THOUSAND_VISITS','VISIT',1000,NULL,N'Thousand visits'),
(N'AVERAGE_NIGHTS','NIGHT',1,N'per visit',N'Average nights per visit'),(N'PER_100000_LIVE_BIRTHS','RATIO',1,N'100,000 live births',N'Per 100,000 live births'),
(N'PER_1000_UNINFECTED_POPULATION','RATIO',1,N'1,000 uninfected population',N'Per 1,000 uninfected population'),
(N'PER_100000_POPULATION','RATIO',1,N'100,000 population',N'Per 100,000 population'),(N'PERCENT','RATIO',0.01,N'100 population',N'Percent')
)s(code,kind,scale,denominator,title) ON t.unit_code=s.code
WHEN MATCHED THEN UPDATE SET quantity_kind=s.kind,scale_factor=s.scale,denominator_text=s.denominator,title=s.title,status='PROVISIONAL_APPROVED'
WHEN NOT MATCHED THEN INSERT(unit_code,quantity_kind,scale_factor,denominator_text,title,status)VALUES(s.code,s.kind,s.scale,s.denominator,s.title,'PROVISIONAL_APPROVED');

MERGE platform.data_quality_policy t USING(VALUES(N'KIDS_AGGREGATE_QUALITY_V1',N'{"period":{"required":true,"pattern":"^[0-9]{4}$"},"dimension":{"required":true,"publishedAliasRequired":true},"value":{"numericRequired":true,"finite":true,"minimum":0},"percent":{"minimum":0,"maximum":100},"counts":{"integerExpected":true},"duplicates":"REJECT_BY_CARRIER_PERIOD_AGE","overlappingAgeGroups":true,"crossAgeAggregation":"FORBIDDEN","sourceLineageRequired":true}'))s(code,rules) ON t.policy_code=s.code
WHEN MATCHED THEN UPDATE SET status='PROVISIONAL_APPROVED',rules_json=s.rules WHEN NOT MATCHED THEN INSERT(policy_code,status,rules_json)VALUES(s.code,'PROVISIONAL_APPROVED',s.rules);
MERGE platform.confidentiality_policy t USING(VALUES(N'KIDS_PUBLIC_AGGREGATE_V1',N'{"dataClass":"PUBLIC_AGGREGATE","containsMicrodata":false,"containsDirectIdentifier":false,"sourcePublicationPreserved":true,"smallCountThreshold":5,"smallCountAction":"FLAG_FOR_REVIEW_NO_AUTOMATIC_REWRITE","defaultConfStatus":"F","publicationScope":"PUBLIC"}'))s(code,rules) ON t.policy_code=s.code
WHEN MATCHED THEN UPDATE SET status='PROVISIONAL_APPROVED',rules_json=s.rules WHEN NOT MATCHED THEN INSERT(policy_code,status,rules_json)VALUES(s.code,'PROVISIONAL_APPROVED',s.rules);

DECLARE @product BIGINT=(SELECT product_id FROM platform.data_product WHERE product_code=N'KIDS_PORTAL');
DECLARE @contract BIGINT=(SELECT contract_id FROM platform.ingestion_contract WHERE contract_code=N'KIDS_PORTAL_V1');
DECLARE @resourceDataset BIGINT=(SELECT dataset_id FROM platform.dataset WHERE product_id=@product AND dataset_code=N'KIDS_RESOURCE');
DECLARE @measure BIGINT=(SELECT measure_id FROM platform.measure WHERE measure_code=N'KIDS_OBS_VALUE_INPUT');
DECLARE @dataflow BIGINT=(SELECT dataflow_id FROM platform.statistical_dataflow WHERE product_id=@product AND dataflow_code=N'KIDS_FILES_STATISTICS');
IF @product IS NULL OR @contract IS NULL OR @resourceDataset IS NULL OR @measure IS NULL OR @dataflow IS NULL THROW 51000,'KIDS revision-7 prerequisites are missing',1;

