INSERT platform.metric(metric_code,source_dataset_id,measure_id,aggregation,allowed_dimension_set_json,status)
SELECT s.metric_code,@resourceDataset,@measure,'NONE',N'["TIME_PERIOD","AGE_GROUP"]','PROVISIONAL_APPROVED' FROM @semantic s
WHERE NOT EXISTS(SELECT 1 FROM platform.metric m WHERE m.metric_code=s.metric_code);
MERGE platform.metric_semantic_profile t USING(SELECT m.metric_id,s.resource_key,u.unit_id,s.confidence,s.rationale FROM @semantic s JOIN platform.metric m ON m.metric_code=s.metric_code JOIN platform.statistical_unit u ON u.unit_code=s.unit_code)s
ON t.metric_id=s.metric_id WHEN MATCHED THEN UPDATE SET source_resource_external_key=s.resource_key,unit_id=s.unit_id,inference_method='TITLE_RANGE_STANDARD_INFERENCE',inference_confidence=s.confidence,inference_rationale=s.rationale,approved_basis=N'DELEGATED_OWNER_AUTHORIZATION_2026_09_10',status='PROVISIONAL_APPROVED'
WHEN NOT MATCHED THEN INSERT(metric_id,source_resource_external_key,unit_id,inference_method,inference_confidence,inference_rationale,approved_basis,status)VALUES(s.metric_id,s.resource_key,s.unit_id,'TITLE_RANGE_STANDARD_INFERENCE',s.confidence,s.rationale,N'DELEGATED_OWNER_AUTHORIZATION_2026_09_10','PROVISIONAL_APPROVED');
DECLARE @quality BIGINT=(SELECT quality_policy_id FROM platform.data_quality_policy WHERE policy_code=N'KIDS_AGGREGATE_QUALITY_V1'),@conf BIGINT=(SELECT confidentiality_policy_id FROM platform.confidentiality_policy WHERE policy_code=N'KIDS_PUBLIC_AGGREGATE_V1');
MERGE platform.statistical_semantic_binding t USING(SELECT @dataflow dataflow_id,CONCAT(N'CARRIER|',s.resource_key) carrier,m.metric_id,u.unit_id FROM @semantic s JOIN platform.metric m ON m.metric_code=s.metric_code JOIN platform.statistical_unit u ON u.unit_code=s.unit_code)s
ON t.dataflow_id=s.dataflow_id AND t.carrier_external_code=s.carrier WHEN MATCHED THEN UPDATE SET metric_id=s.metric_id,unit_id=s.unit_id,aggregation='NONE',obs_status='A',conf_status='F',quality_policy_id=@quality,confidentiality_policy_id=@conf,status='PROVISIONAL_APPROVED'
WHEN NOT MATCHED THEN INSERT(dataflow_id,carrier_external_code,metric_id,unit_id,aggregation,obs_status,conf_status,quality_policy_id,confidentiality_policy_id,status)VALUES(s.dataflow_id,s.carrier,s.metric_id,s.unit_id,'NONE','A','F',@quality,@conf,'PROVISIONAL_APPROVED');

/* DSD revision 2 binds metric/unit/policy semantics without changing observation values. */
IF NOT EXISTS(SELECT 1 FROM platform.statistical_dsd WHERE dataflow_id=@dataflow AND dsd_code=N'KIDS_FILES_STATISTICS_DSD' AND revision=2)
 INSERT platform.statistical_dsd(dataflow_id,dsd_code,revision,observation_grain,status,valid_from)VALUES(@dataflow,N'KIDS_FILES_STATISTICS_DSD',2,N'carrier_code + cell_ordinal','PROVISIONAL_APPROVED','2026-09-10');
DECLARE @oldDsd BIGINT=(SELECT dsd_id FROM platform.statistical_dsd WHERE dataflow_id=@dataflow AND dsd_code=N'KIDS_FILES_STATISTICS_DSD' AND revision=1),@newDsd BIGINT=(SELECT dsd_id FROM platform.statistical_dsd WHERE dataflow_id=@dataflow AND dsd_code=N'KIDS_FILES_STATISTICS_DSD' AND revision=2);
INSERT platform.statistical_component(dsd_id,component_code,component_role,component_order,required,dimension_id,measure_id,classification_version_id,attachment_level,source_field,normalized_field,constraint_json,status)
SELECT @newDsd,component_code,component_role,component_order,required,dimension_id,measure_id,classification_version_id,attachment_level,source_field,normalized_field,constraint_json,'PROVISIONAL_APPROVED' FROM platform.statistical_component c WHERE c.dsd_id=@oldDsd AND NOT EXISTS(SELECT 1 FROM platform.statistical_component x WHERE x.dsd_id=@newDsd AND x.component_code=c.component_code);

/* Revision 7 extends the r6 site contract with units, metrics and carrier bindings. */
DECLARE @doc NVARCHAR(MAX)=N'{"contract":"KIDS_PORTAL_V1","revision":7,"parent":6,"compatibility":"BACKWARD_COMPATIBLE","accessProfile":"ACCESS_CANONICAL_R7_SEMANTIC","datasets":15,"fields":104,"relations":21,"semanticBindings":43,"aggregation":"NONE","qualityPolicy":"KIDS_AGGREGATE_QUALITY_V1","confidentialityPolicy":"KIDS_PUBLIC_AGGREGATE_V1"}';
DECLARE @parent BIGINT=(SELECT site_contract_revision_id FROM platform.site_contract_revision WHERE contract_code=N'KIDS_PORTAL_V1' AND revision=6);
IF NOT EXISTS(SELECT 1 FROM platform.site_contract_revision WHERE contract_code=N'KIDS_PORTAL_V1' AND revision=7) INSERT platform.site_contract_revision(product_id,contract_code,revision,parent_revision_id,schema_standard,compatibility_mode,status,contract_checksum,contract_document_json)VALUES(@product,N'KIDS_PORTAL_V1',7,@parent,N'ISO/IEC 11179 + SDMX information model',N'BACKWARD_COMPATIBLE','APPROVED',CONVERT(VARCHAR(64),HASHBYTES('SHA2_256',CONVERT(VARBINARY(MAX),@doc)),2),@doc);
DECLARE @site7 BIGINT=(SELECT site_contract_revision_id FROM platform.site_contract_revision WHERE contract_code=N'KIDS_PORTAL_V1' AND revision=7);

IF NOT EXISTS(SELECT 1 FROM platform.site_contract_node WHERE site_contract_revision_id=@site7 AND node_code=N'KIDS_ROOT')INSERT platform.site_contract_node(site_contract_revision_id,node_code,node_kind,path_segment,sort_order,title_ka,title_en)VALUES(@site7,N'KIDS_ROOT','SITE_ROOT',N'kids',1,N'ბავშვებისა და მოზარდების სტატისტიკა',N'Children and youth statistics');
DECLARE @root7 BIGINT=(SELECT node_id FROM platform.site_contract_node WHERE site_contract_revision_id=@site7 AND node_code=N'KIDS_ROOT');
INSERT platform.site_contract_node(site_contract_revision_id,node_code,parent_node_id,node_kind,dataset_code,path_segment,sort_order,title_ka,title_en)
SELECT @site7,v.code,@root7,v.kind,v.dataset,v.path,v.ord,v.ka,v.en FROM(VALUES
(N'KIDS_GOALS','ENTITY_COLLECTION',N'KIDS_GOAL',N'goals',10,N'მიზნები',N'Goals'),(N'KIDS_RESOURCES','ENTITY_COLLECTION',N'KIDS_RESOURCE',N'resources',20,N'რესურსები',N'Resources'),(N'KIDS_GLOSSARY','ENTITY_COLLECTION',N'KIDS_GLOSSARY_ENTRY',N'glossary',30,N'ლექსიკონი',N'Glossary'),(N'KIDS_STATISTICS','STATISTICAL_DATAFLOW',N'KIDS_STATISTICAL_INPUT',N'statistics',40,N'სტატისტიკა',N'Statistics'),(N'KIDS_CLASSIFIERS','REFERENCE_REGISTRY',N'KIDS_CLASSIFIER_ITEM',N'classifiers',50,N'კლასიფიკატორები',N'Classifiers'))v(code,kind,dataset,path,ord,ka,en) WHERE NOT EXISTS(SELECT 1 FROM platform.site_contract_node n WHERE n.site_contract_revision_id=@site7 AND n.node_code=v.code);

INSERT platform.site_contract_dataset(site_contract_revision_id,dataset_version_id,dataset_code,access_table_name,data_family,business_grain,natural_key_expression,row_role,load_order,required)
SELECT @site7,dataset_version_id,dataset_code,access_table_name,data_family,business_grain,natural_key_expression,row_role,load_order,required FROM platform.site_contract_dataset d WHERE d.site_contract_revision_id=@parent AND NOT EXISTS(SELECT 1 FROM platform.site_contract_dataset x WHERE x.site_contract_revision_id=@site7 AND x.dataset_code=d.dataset_code);
INSERT platform.site_contract_field(contract_dataset_id,field_name,logical_type,semantic_role,ordinal,required,key_role,classifier_scheme_code,source_expression,normalization_rule)
SELECT target.contract_dataset_id,f.field_name,f.logical_type,f.semantic_role,f.ordinal,f.required,f.key_role,f.classifier_scheme_code,f.source_expression,f.normalization_rule FROM platform.site_contract_field f JOIN platform.site_contract_dataset source ON source.contract_dataset_id=f.contract_dataset_id AND source.site_contract_revision_id=@parent JOIN platform.site_contract_dataset target ON target.site_contract_revision_id=@site7 AND target.dataset_code=source.dataset_code WHERE NOT EXISTS(SELECT 1 FROM platform.site_contract_field x WHERE x.contract_dataset_id=target.contract_dataset_id AND x.field_name=f.field_name);
INSERT platform.site_contract_relation(site_contract_revision_id,relation_code,from_dataset_code,from_field_name,to_dataset_code,to_field_name,relation_kind,cardinality,required,enforcement_policy,load_priority)
SELECT @site7,relation_code,from_dataset_code,from_field_name,to_dataset_code,to_field_name,relation_kind,cardinality,required,enforcement_policy,load_priority FROM platform.site_contract_relation r WHERE r.site_contract_revision_id=@parent AND NOT EXISTS(SELECT 1 FROM platform.site_contract_relation x WHERE x.site_contract_revision_id=@site7 AND x.relation_code=r.relation_code);
INSERT platform.site_contract_classifier(site_contract_revision_id,scheme_code,version_policy,authority_mode,unknown_value_policy,publication_policy)
SELECT @site7,scheme_code,version_policy,authority_mode,unknown_value_policy,publication_policy FROM platform.site_contract_classifier c WHERE c.site_contract_revision_id=@parent AND NOT EXISTS(SELECT 1 FROM platform.site_contract_classifier x WHERE x.site_contract_revision_id=@site7 AND x.scheme_code=c.scheme_code);
INSERT platform.site_contract_gate(site_contract_revision_id,gate_code,gate_type,severity,blocking,rule_json)
SELECT @site7,gate_code,gate_type,severity,blocking,rule_json FROM platform.site_contract_gate g WHERE g.site_contract_revision_id=@parent AND NOT EXISTS(SELECT 1 FROM platform.site_contract_gate x WHERE x.site_contract_revision_id=@site7 AND x.gate_code=g.gate_code);

DECLARE @newSpec TABLE(code NVARCHAR(120),family VARCHAR(24),grain NVARCHAR(500),access_table NVARCHAR(128),natural_key NVARCHAR(1000),row_role VARCHAR(32),load_order INT);
INSERT @newSpec VALUES(N'KIDS_STATISTICAL_UNIT','REFERENCE',N'one governed statistical unit',N'__stat_unit',N'unit_code','REFERENCE',55),(N'KIDS_STATISTICAL_METRIC','REFERENCE',N'one carrier-specific governed metric',N'__stat_metric',N'metric_code','REFERENCE',56),(N'KIDS_STATISTICAL_SEMANTIC_BINDING','RELATION',N'one approved semantic binding per carrier',N'kids_statistical_semantic_binding',N'carrier_code','RELATION',145);
INSERT platform.dataset(product_id,dataset_code,dataset_family,business_grain,lifecycle_status)SELECT @product,s.code,s.family,s.grain,'PROVISIONAL_APPROVED' FROM @newSpec s WHERE NOT EXISTS(SELECT 1 FROM platform.dataset d WHERE d.product_id=@product AND d.dataset_code=s.code);
DECLARE @newCode NVARCHAR(120),@newDataset BIGINT;DECLARE new_cursor CURSOR LOCAL FAST_FORWARD FOR SELECT code FROM @newSpec;OPEN new_cursor;FETCH NEXT FROM new_cursor INTO @newCode;WHILE @@FETCH_STATUS=0 BEGIN SELECT @newDataset=dataset_id FROM platform.dataset WHERE product_id=@product AND dataset_code=@newCode;IF NOT EXISTS(SELECT 1 FROM platform.dataset_version WHERE dataset_id=@newDataset AND version=1)INSERT platform.dataset_version(dataset_id,version,status,effective_from)VALUES(@newDataset,1,'PROVISIONAL_APPROVED',SYSUTCDATETIME());FETCH NEXT FROM new_cursor INTO @newCode;END CLOSE new_cursor;DEALLOCATE new_cursor;
INSERT platform.site_contract_dataset(site_contract_revision_id,dataset_version_id,dataset_code,access_table_name,data_family,business_grain,natural_key_expression,row_role,load_order,required)
SELECT @site7,v.dataset_version_id,s.code,s.access_table,s.family,s.grain,s.natural_key,s.row_role,s.load_order,1 FROM @newSpec s JOIN platform.dataset d ON d.product_id=@product AND d.dataset_code=s.code JOIN platform.dataset_version v ON v.dataset_id=d.dataset_id AND v.version=1 WHERE NOT EXISTS(SELECT 1 FROM platform.site_contract_dataset x WHERE x.site_contract_revision_id=@site7 AND x.dataset_code=s.code);

DECLARE @fields TABLE(dataset_code NVARCHAR(120),ordinal INT,field_name NVARCHAR(128),logical_type VARCHAR(24),semantic_role VARCHAR(32),required BIT,key_role VARCHAR(24));
INSERT @fields VALUES
(N'KIDS_STATISTICAL_UNIT',1,N'unit_code','CODE','NATURAL_KEY',1,'NATURAL'),(N'KIDS_STATISTICAL_UNIT',2,N'quantity_kind','CODE','ATTRIBUTE',1,NULL),(N'KIDS_STATISTICAL_UNIT',3,N'scale_factor','DECIMAL','ATTRIBUTE',1,NULL),(N'KIDS_STATISTICAL_UNIT',4,N'denominator_text','TEXT','ATTRIBUTE',0,NULL),(N'KIDS_STATISTICAL_UNIT',5,N'title','TEXT','CONTENT',1,NULL),
(N'KIDS_STATISTICAL_METRIC',1,N'metric_code','CODE','NATURAL_KEY',1,'NATURAL'),(N'KIDS_STATISTICAL_METRIC',2,N'source_resource_id','CODE','FOREIGN_KEY',1,NULL),(N'KIDS_STATISTICAL_METRIC',3,N'title_ka','TEXT','LOCALIZED_TEXT',0,NULL),(N'KIDS_STATISTICAL_METRIC',4,N'title_en','TEXT','LOCALIZED_TEXT',0,NULL),(N'KIDS_STATISTICAL_METRIC',5,N'measure_component_code','CODE','ATTRIBUTE',1,NULL),(N'KIDS_STATISTICAL_METRIC',6,N'unit_code','CODE','FOREIGN_KEY',1,NULL),(N'KIDS_STATISTICAL_METRIC',7,N'aggregation','CODE','ATTRIBUTE',1,NULL),(N'KIDS_STATISTICAL_METRIC',8,N'lifecycle_state','CODE','ATTRIBUTE',1,NULL),(N'KIDS_STATISTICAL_METRIC',9,N'inference_confidence','DECIMAL','ATTRIBUTE',1,NULL),(N'KIDS_STATISTICAL_METRIC',10,N'inference_rationale','TEXT','ATTRIBUTE',1,NULL),
(N'KIDS_STATISTICAL_SEMANTIC_BINDING',1,N'carrier_code','CODE','NATURAL_KEY',1,'NATURAL'),(N'KIDS_STATISTICAL_SEMANTIC_BINDING',2,N'metric_code','CODE','FOREIGN_KEY',1,NULL),(N'KIDS_STATISTICAL_SEMANTIC_BINDING',3,N'unit_code','CODE','FOREIGN_KEY',1,NULL),(N'KIDS_STATISTICAL_SEMANTIC_BINDING',4,N'aggregation','CODE','ATTRIBUTE',1,NULL),(N'KIDS_STATISTICAL_SEMANTIC_BINDING',5,N'obs_status','CODE','ATTRIBUTE',1,NULL),(N'KIDS_STATISTICAL_SEMANTIC_BINDING',6,N'conf_status','CODE','ATTRIBUTE',1,NULL),(N'KIDS_STATISTICAL_SEMANTIC_BINDING',7,N'quality_policy_code','CODE','ATTRIBUTE',1,NULL),(N'KIDS_STATISTICAL_SEMANTIC_BINDING',8,N'confidentiality_policy_code','CODE','ATTRIBUTE',1,NULL),(N'KIDS_STATISTICAL_SEMANTIC_BINDING',9,N'inference_method','CODE','ATTRIBUTE',1,NULL),(N'KIDS_STATISTICAL_SEMANTIC_BINDING',10,N'operation','CODE','ATTRIBUTE',1,NULL);
INSERT platform.site_contract_field(contract_dataset_id,field_name,logical_type,semantic_role,ordinal,required,key_role)SELECT d.contract_dataset_id,f.field_name,f.logical_type,f.semantic_role,f.ordinal,f.required,f.key_role FROM @fields f JOIN platform.site_contract_dataset d ON d.site_contract_revision_id=@site7 AND d.dataset_code=f.dataset_code WHERE NOT EXISTS(SELECT 1 FROM platform.site_contract_field x WHERE x.contract_dataset_id=d.contract_dataset_id AND x.field_name=f.field_name);
DECLARE @relations TABLE(code NVARCHAR(120),fd NVARCHAR(120),ff NVARCHAR(128),td NVARCHAR(120),tf NVARCHAR(128),card VARCHAR(24),priority INT);INSERT @relations VALUES(N'METRIC_FOR_RESOURCE',N'KIDS_STATISTICAL_METRIC',N'source_resource_id',N'KIDS_RESOURCE',N'source_resource_id','ONE_TO_ONE',122),(N'METRIC_UNIT',N'KIDS_STATISTICAL_METRIC',N'unit_code',N'KIDS_STATISTICAL_UNIT',N'unit_code','MANY_TO_ONE',123),(N'SEMANTIC_FOR_CARRIER',N'KIDS_STATISTICAL_SEMANTIC_BINDING',N'carrier_code',N'KIDS_STATISTICAL_CARRIER',N'carrier_code','ONE_TO_ONE',146),(N'SEMANTIC_METRIC',N'KIDS_STATISTICAL_SEMANTIC_BINDING',N'metric_code',N'KIDS_STATISTICAL_METRIC',N'metric_code','MANY_TO_ONE',147),(N'SEMANTIC_UNIT',N'KIDS_STATISTICAL_SEMANTIC_BINDING',N'unit_code',N'KIDS_STATISTICAL_UNIT',N'unit_code','MANY_TO_ONE',148);
INSERT platform.site_contract_relation(site_contract_revision_id,relation_code,from_dataset_code,from_field_name,to_dataset_code,to_field_name,relation_kind,cardinality,required,enforcement_policy,load_priority)SELECT @site7,code,fd,ff,td,tf,'FOREIGN_KEY',card,1,'ACCESS_AND_INGEST',priority FROM @relations r WHERE NOT EXISTS(SELECT 1 FROM platform.site_contract_relation x WHERE x.site_contract_revision_id=@site7 AND x.relation_code=r.code);

/* Preserve r6 active bindings, then issue and snapshot r7. */
UPDATE platform.contract_source SET active=0 WHERE contract_id=@contract;
MERGE platform.contract_source t USING(
 SELECT @contract contract_id,N'ACCESS.'+d.access_table_name source_locator,'ACCESS_TABLE' source_kind,d.dataset_version_id,d.natural_key_expression source_key_expression,d.row_role,d.load_order,CONCAT(N'{"approvalState":"PROVISIONAL_APPROVED","canonicalAccessRevision":7,"datasetCode":"',d.dataset_code,N'","qualityPolicy":"KIDS_AGGREGATE_QUALITY_V1","confidentialityPolicy":"KIDS_PUBLIC_AGGREGATE_V1"}') mapping_spec_json
 FROM platform.site_contract_dataset d WHERE d.site_contract_revision_id=@site7
)s ON t.contract_id=s.contract_id AND t.source_locator=s.source_locator
WHEN MATCHED THEN UPDATE SET source_kind=s.source_kind,target_dataset_version_id=s.dataset_version_id,source_key_expression=s.source_key_expression,row_role=s.row_role,load_order=s.load_order,mapping_spec_json=s.mapping_spec_json,active=1
WHEN NOT MATCHED THEN INSERT(contract_id,source_locator,source_kind,target_dataset_version_id,source_key_expression,row_role,load_order,mapping_spec_json,active)VALUES(s.contract_id,s.source_locator,s.source_kind,s.dataset_version_id,s.source_key_expression,s.row_role,s.load_order,s.mapping_spec_json,1);
UPDATE platform.ingestion_contract SET contract_revision=7,format_profile='ACCESS_CANONICAL_R7_SEMANTIC',status='PROVISIONAL_APPROVED',auto_publish=0 WHERE contract_id=@contract;
IF NOT EXISTS(SELECT 1 FROM platform.ingestion_contract_revision WHERE contract_id=@contract AND revision=7)INSERT platform.ingestion_contract_revision(contract_id,revision,format_profile,lifecycle_status,compatibility_mode)VALUES(@contract,7,'ACCESS_CANONICAL_R7_SEMANTIC','PROVISIONAL_APPROVED','BACKWARD_COMPATIBLE');
DECLARE @ingestion7 BIGINT=(SELECT ingestion_contract_revision_id FROM platform.ingestion_contract_revision WHERE contract_id=@contract AND revision=7);
INSERT platform.contract_revision_source(ingestion_contract_revision_id,source_locator,source_kind,target_dataset_version_id,source_key_expression,row_role,load_order,mapping_spec_json)SELECT @ingestion7,source_locator,source_kind,target_dataset_version_id,source_key_expression,row_role,load_order,mapping_spec_json FROM platform.contract_source cs WHERE cs.contract_id=@contract AND cs.active=1 AND NOT EXISTS(SELECT 1 FROM platform.contract_revision_source x WHERE x.ingestion_contract_revision_id=@ingestion7 AND x.source_locator=cs.source_locator);
